package local.skyfamily;
import android.app.AlertDialog;import android.content.*;import android.net.Uri;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.util.*;
public class SchoolActivity extends HubActivity {
 final Handler schoolTimer=new Handler();String noteId="",noteClass="",pdfReturn="";EditText noteTitle,noteSection,noteText;StudyInk noteInk;JSONArray noteRefs;LinearLayout refList;TextView savedStatus;boolean dirty=false;final HashMap<String,JSONObject> unsaved=new HashMap<>();SchoolDb db(){return SchoolDb.get(this);}
 @Override void home(){super.home();button("School / notebooks and agenda",()->schoolHome());View entry=body.getChildAt(body.getChildCount()-1);body.removeView(entry);body.addView(entry,1);}
 @Override void page(String title){flushSchool();noteId="";noteTitle=noteSection=noteText=null;noteInk=null;noteRefs=null;refList=null;savedStatus=null;super.page(title);}
 EditText field(String label,String value,int max){text(label);EditText e=input(label,value);e.setFilters(new InputFilter[]{new InputFilter.LengthFilter(max)});return e;}
 void attempt(Runnable action){try{action.run();}catch(Exception e){toast("School: "+e.getMessage());}}
 void schoolHome(){page("School");text("Class notebooks, saved school notes and assignments. Separate from Daily Notes. Stored on this device; no Microsoft or cloud sign-in.");button("School agenda",()->agenda(0,""));button("Search school notes",()->schoolSearch());button("New class notebook",()->nameNotebook(""));button("Export school data / JSON",()->exportSchool());section("Class notebooks");attempt(()->{JSONArray list=db().rows("SELECT * FROM notebooks ORDER BY name COLLATE NOCASE");for(int i=0;i<list.length();i++){JSONObject n=list.optJSONObject(i);button(n.optString("name"),()->notebook(n.optString("id")));}});if(!unsaved.isEmpty())text("A save failed in this session. Drafts remain in memory while the app stays open. Resolve device storage and reopen/save those pages before closing.");}
 void nameNotebook(String id){EditText name=new EditText(this);JSONObject old=id.isEmpty()?null:db().one("notebooks",id);if(old!=null)name.setText(old.optString("name"));name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(80)});new AlertDialog.Builder(this).setTitle(id.isEmpty()?"New class notebook":"Rename notebook").setView(name).setPositiveButton("Save",(d,w)->attempt(()->{String value=name.getText().toString().trim();if(value.isEmpty()){toast("Enter a notebook name");return;}String target=id;if(id.isEmpty())target=db().notebook(value);else db().exec("UPDATE notebooks SET name=? WHERE id=?",value,id);notebook(target);})).setNegativeButton("Cancel",null).show();}
 void notebook(String id){page("Class notebook");JSONObject n=db().one("notebooks",id);if(n==null){schoolHome();return;}text(n.optString("name"));button("New school note",()->attempt(()->schoolNote(db().page(id))));button("Assignments for this class",()->agenda(0,id));button("Rename notebook",()->nameNotebook(id));JSONArray pages=db().rows("SELECT id,title,section FROM pages WHERE notebook=? ORDER BY section COLLATE NOCASE,updated DESC",id);String section="";for(int i=0;i<pages.length();i++){JSONObject p=pages.optJSONObject(i);if(!section.equals(p.optString("section"))){section=p.optString("section");section(section);}button(p.optString("title"),()->schoolNote(p.optString("id")));}if(pages.length()==0)text("No pages yet. Add a lesson, revision page or homework note.");button("Back to School",()->schoolHome());if(!id.equals("general"))button("Delete notebook",()->new AlertDialog.Builder(this).setMessage("Delete this notebook, all its pages and its assignments? This cannot be undone.").setPositiveButton("Delete",(d,w)->attempt(()->{db().exec("DELETE FROM notebooks WHERE id=?",id);schoolHome();})).setNegativeButton("Cancel",null).show());}
 void schoolNote(String id){page("School note");attempt(()->{JSONObject p=unsaved.containsKey(id)?unsaved.get(id):db().one("pages",id);if(p==null){schoolHome();return;}StudyInk.Model model;JSONArray references;try{model=StudyInk.Model.parse(p.optString("ink","[]"));references=new JSONArray(p.optString("refs","[]"));}catch(Exception e){text("Cannot load this note safely. Existing saved data has not been replaced.");return;}noteClass=p.optString("notebook");button("Back to class notebook",()->notebook(noteClass));noteTitle=field("Page title",p.optString("title"),120);noteSection=field("Section",p.optString("section","Notes"),80);noteText=field("School notes",p.optString("body"),50000);noteText.setMinLines(7);noteText.setGravity(Gravity.TOP);noteText.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE|android.text.InputType.TYPE_TEXT_FLAG_CAP_SENTENCES);section("Handwriting / sketches");text("Choose Draw or Highlight to write. Choose Scroll to move the page. This canvas is saved with the school note.");noteInk=new StudyInk(this,model,()->changedSchool());LinearLayout tools=new LinearLayout(this);body.addView(tools,new LinearLayout.LayoutParams(-1,dp(54)));inkControl(tools,"Draw",()->{noteInk.writing=true;noteInk.color=0xff245cb3;noteInk.width=4;});inkControl(tools,"Highlight",()->{noteInk.writing=true;noteInk.color=0x66ffcf33;noteInk.width=22;});inkControl(tools,"Scroll",()->noteInk.writing=false);inkControl(tools,"Undo",()->{noteInk.model.undo();noteInk.invalidate();changedSchool();});inkControl(tools,"Clear",()->new AlertDialog.Builder(this).setMessage("Clear handwriting on this school page?").setPositiveButton("Clear",(d,w)->{noteInk.model.clear();noteInk.invalidate();changedSchool();}).setNegativeButton("Cancel",null).show());body.addView(noteInk,new LinearLayout.LayoutParams(-1,dp(350)));savedStatus=new TextView(this);savedStatus.setTextColor(accent);savedStatus.setText("Saved on this device");body.addView(savedStatus);noteRefs=references;refList=new LinearLayout(this);refList.setOrientation(1);body.addView(refList);button("Link a bookshelf PDF",()->linkPdf());button("Save school note now",()->{dirty=true;flushSchool();});button("Delete this school page",()->new AlertDialog.Builder(this).setMessage("Delete this school page and its saved handwriting? Original PDFs are not deleted.").setPositiveButton("Delete",(d,w)->attempt(()->{String current=noteId,parent=noteClass;schoolTimer.removeCallbacksAndMessages(null);dirty=false;noteId="";db().exec("DELETE FROM pages WHERE id=?",current);unsaved.remove(current);notebook(parent);})).setNegativeButton("Cancel",null).show());noteId=id;dirty=unsaved.containsKey(id);renderRefs();TextWatcher watch=new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int start,int before,int count){changedSchool();}public void afterTextChanged(Editable e){}};noteTitle.addTextChangedListener(watch);noteSection.addTextChangedListener(watch);noteText.addTextChangedListener(watch);});}
 void inkControl(LinearLayout row,String label,Runnable action){TextView t=new TextView(this);t.setText(label);t.setTextColor(fg);t.setGravity(Gravity.CENTER);t.setTextSize(13);t.setFocusable(true);row.addView(t,new LinearLayout.LayoutParams(0,-1,1));t.setOnClickListener(v->action.run());}
 void changedSchool(){if(noteId.isEmpty())return;dirty=true;if(savedStatus!=null)savedStatus.setText("Saving school note...");schoolTimer.removeCallbacksAndMessages(null);schoolTimer.postDelayed(()->flushSchool(),650);}
 void flushSchool(){schoolTimer.removeCallbacksAndMessages(null);if(!dirty||noteId.isEmpty()||noteText==null||noteInk==null)return;String title=noteTitle.getText().toString().trim(),section=noteSection.getText().toString().trim(),ink=noteInk.model.json(),refs=noteRefs.toString(),text=noteText.getText().toString();if(title.isEmpty())title="Untitled page";if(section.isEmpty())section="Notes";try{JSONObject draft=new JSONObject().put("id",noteId).put("notebook",noteClass).put("title",title).put("section",section).put("body",text).put("ink",ink).put("refs",refs);unsaved.put(noteId,draft);db().exec("UPDATE pages SET section=?,title=?,body=?,ink=?,refs=?,updated=? WHERE id=?",section,title,text,ink,refs,System.currentTimeMillis(),noteId);unsaved.remove(noteId);dirty=false;if(savedStatus!=null)savedStatus.setText("Saved on this device / "+new Date());}catch(Exception e){if(savedStatus!=null)savedStatus.setText("NOT SAVED / "+e.getMessage());toast("School save failed. Keep app open and check device storage.");}}
 void renderRefs(){refList.removeAllViews();JSONArray books=index();for(int i=0;i<noteRefs.length();i++){String id=noteRefs.optString(i);JSONObject found=null;for(int j=0;j<books.length();j++)if(id.equals(books.optJSONObject(j).optString("id")))found=books.optJSONObject(j);final JSONObject book=found;TextView link=new TextView(this);link.setText(book==null?"PDF reference unavailable / book removed":"Open PDF / "+book.optString("title"));link.setTextColor(accent);link.setPadding(0,dp(14),0,dp(14));refList.addView(link);if(book!=null)link.setOnClickListener(v->{pdfReturn=noteId;openBook(book);});final int at=i;link.setOnLongClickListener(v->{JSONArray next=new JSONArray();for(int n=0;n<noteRefs.length();n++)if(n!=at)next.put(noteRefs.opt(n));noteRefs=next;changedSchool();renderRefs();return true;});}}
 void linkPdf(){if(noteRefs.length()>=20){toast("Up to 20 PDF links per page");return;}JSONArray all=index();ArrayList<JSONObject> pdfs=new ArrayList<>();ArrayList<String> names=new ArrayList<>();for(int i=0;i<all.length();i++){JSONObject b=all.optJSONObject(i);if(b!=null&&b.optString("format").equals("PDF")){pdfs.add(b);names.add(b.optString("title"));}}if(pdfs.isEmpty()){toast("Import a PDF through Uploads or Bookshelf first");return;}new AlertDialog.Builder(this).setTitle("Link an existing PDF / long-press link to remove").setItems(names.toArray(new String[0]),(d,w)->{String id=pdfs.get(w).optString("id");for(int i=0;i<noteRefs.length();i++)if(id.equals(noteRefs.optString(i)))return;noteRefs.put(id);changedSchool();renderRefs();}).show();}
 void schoolSearch(){page("Search school notes");EditText query=field("Find words in titles or typed notes","",100);button("Search",()->{String term="%"+query.getText().toString().trim()+"%";JSONArray found=db().rows("SELECT p.id,p.title,p.section,n.name AS course FROM pages p JOIN notebooks n ON n.id=p.notebook WHERE p.title LIKE ? OR p.body LIKE ? ORDER BY p.updated DESC LIMIT 100",term,term);page("School search results");text(found.length()+" results / up to 100. Handwriting and PDF text are not searched.");for(int i=0;i<found.length();i++){JSONObject p=found.optJSONObject(i);button(p.optString("course")+" / "+p.optString("section")+" / "+p.optString("title"),()->schoolNote(p.optString("id")));}button("Search again",()->schoolSearch());});}
 String todaySchool(){return new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 void agenda(int filter,String course){page("School agenda");LinearLayout tabs=new LinearLayout(this);body.addView(tabs,new LinearLayout.LayoutParams(-1,dp(52)));String[] labels={"To do","Done","All"};for(int i=0;i<3;i++){final int f=i;inkControl(tabs,(i==filter?"[":"")+labels[i]+(i==filter?"]":""),()->agenda(f,course));}button("New assignment",()->taskForm("",course));String condition=filter==0?"t.done=0":filter==1?"t.done=1":"1=1";JSONArray tasks=db().rows("SELECT t.*,n.name AS course FROM tasks t JOIN notebooks n ON n.id=t.notebook WHERE (?='' OR t.notebook=?) AND "+condition+" ORDER BY t.done,CASE WHEN t.due='' THEN 1 ELSE 0 END,t.due,t.important DESC",course,course);if(tasks.length()==0)text("No assignments in this view.");for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);CheckBox done=new CheckBox(this);done.setTextColor(fg);done.setText(task.optString("title"));done.setChecked(task.optInt("done")==1);body.addView(done);done.setOnCheckedChangeListener((v,checked)->attempt(()->{db().exec("UPDATE tasks SET done=? WHERE id=?",checked?1:0,task.optString("id"));agenda(filter,course);}));String due=task.optString("due");text(task.optString("course")+" / "+(due.isEmpty()?"No due date":due+(task.optInt("done")==0?(due.compareTo(todaySchool())<0?" / Overdue":due.equals(todaySchool())?" / Today":""):""))+(task.optInt("important")==1?" / Important":""));button("Edit assignment",()->taskForm(task.optString("id"),task.optString("notebook")));}button("All classes",()->agenda(filter,""));button("Back to School",()->schoolHome());text("Local agenda only. No notifications, school-portal sync or automatic reminders.");}
 void taskForm(String id,String course){page("School assignment");JSONObject old=id.isEmpty()?new JSONObject():db().one("tasks",id);if(old==null){agenda(0,"");return;}JSONArray courses=db().rows("SELECT * FROM notebooks ORDER BY name");ArrayList<String> names=new ArrayList<>();int selected=0;for(int i=0;i<courses.length();i++){JSONObject n=courses.optJSONObject(i);names.add(n.optString("name"));if(n.optString("id").equals(old.optString("notebook",course)))selected=i;}Spinner notebook=new Spinner(this);notebook.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));notebook.setSelection(selected);body.addView(notebook);EditText title=field("Assignment",old.optString("title"),120),due=field("Due date YYYY-MM-DD / optional",old.optString("due"),10),detail=field("Instructions or checklist text",old.optString("detail"),5000);detail.setMinLines(4);CheckBox important=new CheckBox(this);important.setText("Important");important.setChecked(old.optInt("important")==1);body.addView(important);button("Save assignment",()->attempt(()->{String name=title.getText().toString().trim(),date=due.getText().toString().trim();if(name.isEmpty()){toast("Enter an assignment title");return;}if(!date.isEmpty())try{if(!date.matches("[0-9]{4}-[0-9]{2}-[0-9]{2}"))throw new Exception();java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);format.setLenient(false);format.parse(date);}catch(Exception e){toast("Enter a valid YYYY-MM-DD date");return;}String parent=courses.optJSONObject(notebook.getSelectedItemPosition()).optString("id");if(id.isEmpty()){db().limit("tasks",1000);db().exec("INSERT INTO tasks VALUES(?,?,?,?,?,?,?)",UUID.randomUUID().toString(),parent,name,detail.getText().toString(),date,important.isChecked()?1:0,0);}else db().exec("UPDATE tasks SET notebook=?,title=?,detail=?,due=?,important=? WHERE id=?",parent,name,detail.getText().toString(),date,important.isChecked()?1:0,id);agenda(0,parent);}));if(!id.isEmpty())button("Delete assignment",()->new AlertDialog.Builder(this).setMessage("Delete this assignment?").setPositiveButton("Delete",(d,w)->attempt(()->{db().exec("DELETE FROM tasks WHERE id=?",id);agenda(0,"");})).setNegativeButton("Cancel",null).show());}
 @Override void openBook(JSONObject book){super.openBook(book);if(pdf==null){pdfReturn="";return;}PdfPane pane=pdf;int at=pane.indexOfChild(pane.image);ViewGroup.LayoutParams size=pane.image.getLayoutParams();pane.removeView(pane.image);PdfMarkup markup=new PdfMarkup(pane);pane.addView(markup,at,size);LinearLayout tools=new LinearLayout(this);pane.addView(tools,1,new LinearLayout.LayoutParams(-1,dp(52)));inkControl(tools,"Pan",()->markup.tool=0);inkControl(tools,"Pen",()->markup.tool=1);inkControl(tools,"Highlight",()->markup.tool=2);inkControl(tools,"Undo",()->markup.undo());inkControl(tools,"Clear",()->new AlertDialog.Builder(this).setMessage("Clear temporary marks on this PDF page?").setPositiveButton("Clear",(d,w)->markup.clearPage()).setNegativeButton("Cancel",null).show());final String back=pdfReturn;pdfReturn="";inkControl(tools,"School",()->{if(back.isEmpty())schoolHome();else schoolNote(back);});TextView warning=new TextView(this);warning.setText("Temporary PDF marks / NOT SAVED. Use Pan for zoom, drag and page swipe.");warning.setTextColor(accent);warning.setGravity(Gravity.CENTER);pane.addView(warning,2,new LinearLayout.LayoutParams(-1,-2));}
 void exportSchool(){flushSchool();if(!unsaved.isEmpty()){toast("Resolve failed school saves before exporting");return;}if(Build.VERSION.SDK_INT>=19){Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"School-data.json");try{startActivityForResult(i,941);}catch(Exception e){toast("No document picker available");}}else{File dir=getExternalFilesDir(null);if(dir==null){toast("External app storage unavailable");return;}File file=new File(dir,"School-data-"+System.currentTimeMillis()+".json");work(()->{try(OutputStream out=new FileOutputStream(file)){db().export(out);}ui.post(()->toast("Export saved to "+file.getAbsolutePath()));});}}
 @Override protected void onActivityResult(int request,int result,Intent data){if(request!=941){super.onActivityResult(request,result,data);return;}if(result!=RESULT_OK||data==null||data.getData()==null)return;final Uri uri=data.getData();flushSchool();work(()->{try(OutputStream out=getContentResolver().openOutputStream(uri)){if(out==null)throw new IOException("Cannot open export destination");db().export(out);}ui.post(()->toast("School data exported. Original PDF files are separate."));});}
 @Override protected void onPause(){flushSchool();super.onPause();}
 @Override protected void onDestroy(){flushSchool();schoolTimer.removeCallbacksAndMessages(null);super.onDestroy();}
}
